def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 == 0:
        return None

    value = v1 / (v2 / 1000000)

    return {
        "value": value,
        "trace": {
            "cash_proceeds_millions": v1,
            "warrants_exercised": v2,
            "cash_proceeds_dollars": v1 / (1 / 1000000),
            "output_meta": {
                "currency": "USD",
                "scale": null,
                "unit": "share price"
            }
        }
    }
